-- ------------------------------------------------------------------------
-- 0048_record_audit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Database-enforced audit trail. The client-side audit_log records user actions,
-- but a defensible Part 11 / QMS audit trail must be created by the database so
-- it cannot be bypassed or altered. record_audit captures every INSERT / UPDATE
-- / DELETE on the quality-record tables, with the acting user, timestamp and the
-- before/after row. It is written only by SECURITY DEFINER triggers, read only
-- by admins, and never updatable/deletable by users.
-- ===========================================================================

create table if not exists public.record_audit (
  id          bigint generated always as identity primary key,
  table_name  text not null,
  op          text not null,           -- INSERT | UPDATE | DELETE
  record_key  text,                    -- ucn / uid / call_number / id
  actor       uuid,
  actor_email text,
  changed_at  timestamptz not null default now(),
  old_data    jsonb,
  new_data    jsonb
);
create index if not exists record_audit_at_idx  on public.record_audit (changed_at desc);
create index if not exists record_audit_tbl_idx on public.record_audit (table_name, changed_at desc);
create index if not exists record_audit_key_idx on public.record_audit (record_key);

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare j jsonb;
begin
  if tg_op = 'DELETE' then j := to_jsonb(old); else j := to_jsonb(new); end if;
  insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
  values (
    tg_table_name, tg_op,
    coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
    auth.uid(), auth.email(),
    case when tg_op <> 'INSERT' then to_jsonb(old) else null end,
    case when tg_op <> 'DELETE' then to_jsonb(new) else null end
  );
  return case when tg_op = 'DELETE' then old else new end;
end $$;

alter table public.record_audit enable row level security;
grant select on public.record_audit to authenticated;   -- read only; no insert/update/delete grant
drop policy if exists record_audit_read on public.record_audit;
create policy record_audit_read on public.record_audit for select
  using (public.is_admin() or public.has_perm('audit.view'));

-- Attach to the quality-record tables that exist.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('create trigger record_audit_t after insert or update or delete on public.%I for each row execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0049_record_retention_guard.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- Record-retention guard. Quality records must be retained, not deleted — an
-- auditor expects that a service record, visit report or spare request cannot
-- be removed. Hard DELETE on these append-only quality tables is blocked; the
-- app uses status / cancel / drop workflows instead, which are captured by the
-- audit trail. (Configuration/operational tables are not covered here.)
-- ===========================================================================

create or replace function public.block_hard_delete()
returns trigger language plpgsql as $$
begin
  -- Application deletion (the authenticated role, via PostgREST) is blocked for
  -- retention. Controlled deletion by a DBA/superuser (e.g. an approved archival
  -- procedure in the SQL editor) is permitted and is still captured by the
  -- database audit trail.
  if current_user = 'authenticated' then
    raise exception
      'RECORD RETENTION: % records cannot be deleted (row %). Use the defined status / cancel / drop workflow.',
      tg_table_name,
      coalesce(to_jsonb(old)->>'ucn', to_jsonb(old)->>'uid', to_jsonb(old)->>'call_number', to_jsonb(old)->>'id');
  end if;
  return old;
end $$;

do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists no_hard_delete on public.%I', t);
      execute format('create trigger no_hard_delete before delete on public.%I for each row execute function public.block_hard_delete()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0103_record_audit_not_bulk.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- THE AUDIT TRAIL RECORDS WHAT PEOPLE DO, NOT WHAT A LOAD LOADED.
--
-- `record_audit` (0048) kept a row, with the whole record before and after, for
-- every INSERT / UPDATE / DELETE on the quality tables. That is right for a
-- person changing a record and wrong for a bulk load: migrating the sheet era
-- wrote tens of thousands of audit rows that say nothing a migration report
-- does not say better, and they are the reason the table grew as it did.
--
-- An audit trail exists to answer "who changed this record, and to what". A
-- one-time load is not that question; it is answered by the migration's own
-- verification (the DM checks in the validation package: row counts reconciled,
-- fields sampled, identifiers checked).
--
-- SO A BULK WRITE IS STILL RECORDED — AS ONE EVENT, NOT TEN THOUSAND. The row
-- says who loaded, into which table, how many rows and when. The load remains
-- attributable, which is what Part 11 asks of it; what goes is the per-record
-- duplicate of data that is already in the table it was loaded into.
--
-- HOW THE LINE IS DRAWN. A statement-level trigger with transition tables can
-- count the rows one statement touched, which a row-level trigger cannot. The
-- threshold sits between the largest write a PERSON makes in one statement and
-- the smallest a LOADER makes:
--
--     bulk re-allotment   100 rows per statement  (reallocateCalls, src/lib/supabase.ts)
--     bulk upload         300 or 500 per statement (uploadRows, same file)
--
-- 150 sits between them, and if either chunk size changes this number wants
-- revisiting. But the margin is wider than those numbers suggest, and it is
-- worth knowing why:
--
--   THE BULK USER ACTIONS GO THROUGH THE `calls` VIEW, and 0040's INSTEAD OF
--   triggers write it ROW BY ROW into the typed table. So at the table — which
--   is where this trigger sits — a hundred-call re-allotment arrives as a
--   hundred single-row statements and is audited in full, whatever the
--   threshold. The loaders write to `field_calls`, `spare_requests`,
--   `spare_consumption` and the rest DIRECTLY, in one statement per batch.
--
-- Verified on Postgres, all three: 500 rows loaded into field_calls -> one BULK
-- INSERT row; a re-allotment through the view -> a row each, with before and
-- after intact; a re-load UPDATING 500 rows -> one BULK UPDATE row.
--
-- Everything else is unchanged: written only by a SECURITY DEFINER trigger,
-- readable only by an administrator or `audit.view`, and still not writable or
-- alterable by anyone.
-- ===========================================================================

create or replace function public.record_audit_fn()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  n     bigint;
  bulk  boolean;
begin
  -- How many rows this ONE statement touched.
  if tg_op = 'DELETE' then
    select count(*) into n from old_rows;
  else
    select count(*) into n from new_rows;
  end if;
  if n = 0 then return null; end if;

  bulk := n > 150;

  if bulk then
    -- One row for the whole statement: who, what table, how many, when.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    values (tg_table_name, 'BULK ' || tg_op, null, auth.uid(), auth.email(), null,
            jsonb_build_object('rows', n,
                               'note', 'Bulk write — recorded as one event. The records are in ' || tg_table_name || '.'));
    return null;
  end if;

  -- Otherwise exactly what 0048 did, a row at a time, from the transition
  -- tables rather than from OLD / NEW.
  if tg_op = 'INSERT' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), null, j
      from (select to_jsonb(r) as j from new_rows r) x;
  elsif tg_op = 'DELETE' then
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(j->>'ucn', j->>'uid', j->>'line_uid', j->>'call_number', j->>'id'),
           auth.uid(), auth.email(), j, null
      from (select to_jsonb(r) as j from old_rows r) x;
  else
    -- UPDATE: the before and after of the same record, paired on the key the
    -- audit is written under. A quality table without one of these keys cannot
    -- be paired, so both images are still written and the key reads null.
    insert into public.record_audit (table_name, op, record_key, actor, actor_email, old_data, new_data)
    select tg_table_name, tg_op,
           coalesce(nj->>'ucn', nj->>'uid', nj->>'line_uid', nj->>'call_number', nj->>'id'),
           auth.uid(), auth.email(), oj, nj
      from (
        select to_jsonb(nr) as nj,
               (select to_jsonb(orow) from old_rows orow
                 where coalesce(to_jsonb(orow)->>'ucn', to_jsonb(orow)->>'uid', to_jsonb(orow)->>'line_uid',
                                to_jsonb(orow)->>'call_number', to_jsonb(orow)->>'id')
                       is not distinct from
                       coalesce(to_jsonb(nr)->>'ucn', to_jsonb(nr)->>'uid', to_jsonb(nr)->>'line_uid',
                                to_jsonb(nr)->>'call_number', to_jsonb(nr)->>'id')
                 limit 1) as oj
          from new_rows nr
      ) x;
  end if;
  return null;
end $$;

-- Re-attach: one trigger PER OPERATION now, because a statement trigger names
-- the transition table it needs and INSERT has no OLD, DELETE no NEW.
do $$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports',
    'spare_requests', 'spare_request_lines', 'spare_consumption', 'feedback',
    'call_requests', 'pending_registrations'
  ] loop
    if to_regclass('public.' || t) is not null
       and (select relkind from pg_class where oid = ('public.' || t)::regclass) = 'r' then
      execute format('drop trigger if exists record_audit_t on public.%I', t);
      execute format('drop trigger if exists record_audit_i on public.%I', t);
      execute format('drop trigger if exists record_audit_u on public.%I', t);
      execute format('drop trigger if exists record_audit_d on public.%I', t);
      execute format('create trigger record_audit_i after insert on public.%I '
                     'referencing new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_u after update on public.%I '
                     'referencing old table as old_rows new table as new_rows for each statement '
                     'execute function public.record_audit_fn()', t);
      execute format('create trigger record_audit_d after delete on public.%I '
                     'referencing old table as old_rows for each statement '
                     'execute function public.record_audit_fn()', t);
    end if;
  end loop;
end $$;

-- ------------------------------------------------------------------------
-- 0112_stop_record_audit.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- STOP WRITING TO record_audit. THE AUDIT LOG IS ENOUGH.
--
-- 0048 added a database-enforced trail — a before/after image of every row
-- written to the ten quality-record tables — because a defensible 21 CFR
-- Part 11 trail has to be created by the database rather than the client.
-- Part 11 is FDA's; this operation is regulated by CDSCO under the Medical
-- Devices Rules, 2017, which asks for records to be controlled and retrievable
-- and does not prescribe that second trail. The user's decision, 2026-09-05:
-- `audit_log` is the trail.
--
-- WHAT THIS DOES AND DOES NOT DO.
--   • The ten triggers are dropped, so nothing writes to `record_audit` again.
--   • The TABLE STAYS, with whatever it already holds. It is a quality record
--     of what happened while it was running, and 0049 forbids deleting those.
--     Dropping it is a separate decision and a separate script.
--   • `record_audit_fn()` stays too, unattached. Re-attaching is then one
--     `create trigger`, not a migration to write again.
--
-- IT IS A REDUCTION, AND THE PACKAGE SAYS SO. `audit_log` is written by the
-- CLIENT: it can be bypassed by a direct API call and it is purged on the
-- retention window. `record_audit` could not be bypassed and was not purged.
-- The validation package is updated in the same change rather than left
-- claiming a control that has been switched off.
-- ===========================================================================

do $stop$
declare t text;
begin
  foreach t in array array[
    'field_calls', 'installation_calls', 'pm_calls', 'reports', 'call_requests',
    'pending_registrations', 'feedback', 'spare_requests', 'spare_request_lines',
    'spare_consumption'
  ] loop
    if to_regclass('public.' || t) is not null then
      execute format('drop trigger if exists record_audit_i on public.%I', t);
      execute format('drop trigger if exists record_audit_u on public.%I', t);
      execute format('drop trigger if exists record_audit_d on public.%I', t);
    end if;
  end loop;
end $stop$;

-- Nothing writes it now, so nothing should think it can. The read policy is
-- left alone: what is already recorded stays readable by an administrator.
comment on table public.record_audit is
  'HISTORICAL. Written by triggers from 0048 until 0112 stopped them (2026-09-05) — audit_log is the trail now. Retained, not maintained: everything here happened while it was running.';

-- ------------------------------------------------------------------------
-- 0166_ffr_retention_guard.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0166 — the Field Failure Register keeps its records.
--
-- Filed in `data_integrity` rather than beside the table (0165), because
-- block_hard_delete() is defined in THIS module and this module runs AFTER
-- daily_review in ALL_ORDER. Putting the trigger next to the table made a fresh
-- apply fail on a function that did not exist yet, which check:replay caught.
--
-- GUARDED on the table's presence, the way the replay tails are: running
-- data_integrity alone against a database that has not had daily_review yet
-- must skip this, not fail.
--
-- Deletion is already impossible for the application without this: 0165 grants
-- no DELETE policy, so a delete as `authenticated` matches no rows and silently
-- affects none. This is the second lock — it turns that silence into a refusal
-- the day somebody adds a delete policy.
-- ===========================================================================
do $$
begin
  if to_regclass('public.field_failure_reports') is not null
     and to_regprocedure('public.block_hard_delete()') is not null then
    execute 'drop trigger if exists no_hard_delete on public.field_failure_reports';
    execute 'create trigger no_hard_delete before delete on public.field_failure_reports '
         || 'for each row execute function public.block_hard_delete()';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0174_ffr_history.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0174 — EVERY CHANGE TO A FIELD FAILURE REPORT IS RECORDED.
--
-- The user, 2026-09-12: "And where is the FFR update? I need to be able to
-- capture everytime it is updated - For log keeping."
--
-- The FFR is reviewed WEEKLY and edited each time — the observation grows, the
-- problem status is written, a CAPA is opened and later closed, the report is
-- closed or cancelled. Today the register holds only the CURRENT state, so the
-- question a weekly cycle actually asks — what changed since last week, and who
-- changed it — has no answer anywhere.
--
-- IN THE DATABASE, NOT THE CLIENT, and that is the whole point of doing it here
-- rather than adding another logAudit() call. The application's audit trail is
-- client-written, so it records what the screen chose to tell it and nothing
-- about an edit made straight through the API (this is stated plainly in the
-- validation package, FRS-021). A change history for a quality record that a
-- caller can decline to write is not a change history. This trigger sees every
-- UPDATE by every path.
--
-- ONE ROW PER UPDATE, not per field. An edit is one act by one person at one
-- moment; splitting it across six rows makes "what did she change on Tuesday"
-- a reassembly job. The fields are held in `changes` as
-- {"column": {"from": …, "to": …}} — only the columns that actually differ.
--
-- AND AN UPDATE THAT CHANGES NOTHING WRITES NOTHING. Re-saving a form without
-- touching it is not an event, and a log full of them is a log nobody reads.
--
-- APPEND-ONLY. No update policy and no delete policy exist, so the history
-- cannot be edited or tidied by anyone through the API — the record of what a
-- record used to say is itself a quality record (0049's rule).
-- ===========================================================================

create table if not exists public.ffr_history (
  id            bigserial primary key,
  ffr_id        bigint      not null references public.field_failure_reports (id) on delete cascade,
  -- The NUMBER as well as the id: the id is an implementation detail, and the
  -- number is what a person reading the log recognises.
  ffr_no        text        not null default '',
  changed_at    timestamptz not null default now(),
  changed_by    uuid        references auth.users (id),
  changed_by_name text      not null default '',
  -- 'update' today; 'create' marks the row the report was raised with, so the
  -- history starts at the beginning rather than at the first edit.
  action        text        not null default 'update',
  changes       jsonb       not null default '{}'::jsonb
);

create index if not exists ffr_history_ffr_idx  on public.ffr_history (ffr_id, changed_at desc);
create index if not exists ffr_history_when_idx on public.ffr_history (changed_at desc);

alter table public.ffr_history enable row level security;

-- WHOEVER MAY READ THE REGISTER MAY READ ITS HISTORY. Anything narrower would
-- mean a report somebody can see whose changes they cannot — which is the
-- question the log exists to answer.
drop policy if exists ffrh_read on public.ffr_history;
create policy ffrh_read on public.ffr_history for select to authenticated
  using ((select public.has_perm('ffr.manage')) or (select public.is_admin()));

-- NO insert policy: the trigger is SECURITY DEFINER and writes as the owner, so
-- a client cannot forge an entry even with the grant below.
-- NO update or delete policy: append-only, by omission rather than by promise.
grant select on public.ffr_history to authenticated;

-- ---------------------------------------------------------------------------
-- WHAT CHANGED. Columns compared as text, which is what the log displays and
-- what makes '2026-09-12' and a date the same thing to a reader.
--
-- The bookkeeping columns are SKIPPED: updated_at moves on every write, and a
-- log whose every entry says "updated_at changed" buries the one that says the
-- CAPA was closed.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_history_write()
returns trigger language plpgsql security definer set search_path = public as $$
declare
  v_old  jsonb := to_jsonb(old);
  v_new  jsonb := to_jsonb(new);
  v_diff jsonb := '{}'::jsonb;
  k      text;
  v_name text;
  -- Not worth an entry: set by the database on every write, or never changed.
  skip   text[] := array['updated_at', 'id', 'ffr_no', 'raised_by', 'created_at'];
begin
  for k in select jsonb_object_keys(v_new) loop
    if k = any (skip) then continue; end if;
    if v_new -> k is distinct from v_old -> k then
      v_diff := v_diff || jsonb_build_object(k, jsonb_build_object('from', v_old -> k, 'to', v_new -> k));
    end if;
  end loop;

  -- Nothing actually changed: re-saving a form untouched is not an event.
  if v_diff = '{}'::jsonb then return null; end if;

  select coalesce(nullif(btrim(d.name), ''), nullif(btrim(p.full_name), ''), p.email)
    into v_name
    from public.profiles p
    left join public.user_directory d
      on lower(btrim(d.email)) = lower(btrim(p.email))
      or lower(btrim(d.gmail)) = lower(btrim(p.email))
   where p.id = auth.uid();

  insert into public.ffr_history (ffr_id, ffr_no, changed_by, changed_by_name, action, changes)
  values (new.id, coalesce(new.ffr_no, ''), auth.uid(), coalesce(v_name, ''), 'update', v_diff);

  return null;
end $$;

drop trigger if exists zz_ffr_history on public.field_failure_reports;
create trigger zz_ffr_history after update on public.field_failure_reports
  for each row execute function public.ffr_history_write();

-- ---------------------------------------------------------------------------
-- THE FIRST ENTRY. A history that begins at the first EDIT cannot say when the
-- report came into being or who raised it, which is the one entry every other
-- one is read against.
-- ---------------------------------------------------------------------------
create or replace function public.ffr_history_created()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.ffr_history (ffr_id, ffr_no, changed_by, changed_by_name, action, changes)
  values (new.id, coalesce(new.ffr_no, ''), new.raised_by, coalesce(new.raised_by_name, ''), 'create',
          jsonb_build_object('ffr_date', jsonb_build_object('from', null, 'to', new.ffr_date),
                             'ucn',      jsonb_build_object('from', null, 'to', new.ucn)));
  return null;
end $$;

drop trigger if exists zz_ffr_history_created on public.field_failure_reports;
create trigger zz_ffr_history_created after insert on public.field_failure_reports
  for each row execute function public.ffr_history_created();

-- ---------------------------------------------------------------------------
-- THE REPORTS THAT ALREADY EXIST get their 'create' entry, so every report on
-- the register has a history that starts somewhere. Idempotent: a report that
-- already has one is skipped, so this file can be re-run.
-- ---------------------------------------------------------------------------
insert into public.ffr_history (ffr_id, ffr_no, changed_at, changed_by, changed_by_name, action, changes)
select f.id, coalesce(f.ffr_no, ''),
       coalesce(f.ffr_date::timestamptz, f.updated_at, now()),
       f.raised_by, coalesce(f.raised_by_name, ''), 'create',
       jsonb_build_object('ffr_date', jsonb_build_object('from', null, 'to', f.ffr_date),
                          'ucn',      jsonb_build_object('from', null, 'to', f.ucn))
  from public.field_failure_reports f
 where not exists (select 1 from public.ffr_history h where h.ffr_id = f.id and h.action = 'create');

-- ---------------------------------------------------------------------------
-- THE RETENTION PURGE MUST NOT REACH IT. 0166 blocks deletion of a field
-- failure report; its history is the same record seen over time, and a log that
-- can be purged while the record it describes cannot is a gap with no reason
-- for being there.
-- ---------------------------------------------------------------------------
do $$
begin
  if to_regprocedure('public.block_hard_delete()') is not null then
    execute 'drop trigger if exists zz_no_delete on public.ffr_history';
    execute 'create trigger zz_no_delete before delete on public.ffr_history
               for each row execute function public.block_hard_delete()';
  else
    raise notice 'block_hard_delete() is not present yet — ffr_history is unprotected until data_integrity.sql runs.';
  end if;
end $$;

-- ------------------------------------------------------------------------
-- 0177_ffr_history_view_right.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- 0177 — THE UPDATE LOG FOLLOWS THE REGISTER.
--
-- 0176 made reading the Field Failure Register its own right (`ffr.view`).
-- 0174 gated the change log on `ffr.manage`, which would now leave somebody
-- able to read a report but NOT what changed on it — and the log exists to be
-- read alongside the record it describes.
--
-- A FILE OF ITS OWN, and not a tidiness choice: `ffrh_read` is created by 0174
-- in the `data_integrity` module, while `ffr_read` belongs to `daily_review`.
-- One migration redefining both would sit in one module and be reverted by a
-- replay of the other — `check:bundles` refuses exactly that, and caught it
-- here before it shipped.
-- ===========================================================================

drop policy if exists ffrh_read on public.ffr_history;
create policy ffrh_read on public.ffr_history for select to authenticated
  using (
        (select public.has_perm('ffr.view'))
     or (select public.has_perm('ffr.manage'))
     or (select public.is_admin())
  );

commit;
